            aOrbiterJ = ((aOrbiterJ ^ aOrbiterA) ^ 0x6C699773430C7EABULL) ^ aOUSaltB[(((511U - aIndex) + 106U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x678F811B9F2564A3ULL), 51U);
