            aOrbiterG = ((aWandererD + RotL64(aPrevious, 36U)) + 0x2DD59257EF3A2A93ULL) + aOASaltD[(((511U - aIndex) + 267U)) & S_SALT1];
            aOrbiterJ = (((aWandererC + RotL64(aCross, 11U)) + RotL64(aCarry, 39U)) + 0x365E3E366214519AULL) + aOASaltE[(((511U - aIndex) + 282U)) & S_SALT1];
            aOrbiterE = ((aWandererG + RotL64(aIngress, 27U)) + 0x64D354DE6330C423ULL) + aOASaltH[((aIndex + 452U)) & S_SALT1];
            aOrbiterD = (((aWandererJ + RotL64(aPrevious, 21U)) + RotL64(aCarry, 23U)) + 0x127451CA221EBC22ULL) + aOASaltC[(((511U - aIndex) + 439U)) & S_SALT1];
            aOrbiterK = ((aWandererI + RotL64(aCross, 53U)) + 0xAF518E3D5CA57B7DULL) + aOASaltA[((aIndex + 316U)) & S_SALT1];
