    std::uint64_t *aOASaltF = pWorkSpace->mDomainBundle.mKeyRotateASalts.mOrbiterAssign.mSaltF;
    std::uint64_t *aOASaltG = pWorkSpace->mDomainBundle.mKeyRotateASalts.mOrbiterAssign.mSaltG;
