    std::uint64_t *aOUSaltA = pWorkSpace->mDomainBundle.mKeyRotateASalts.mOrbiterUpdate.mSaltA;
    std::uint64_t *aOUSaltB = pWorkSpace->mDomainBundle.mKeyRotateASalts.mOrbiterUpdate.mSaltB;
