            //
            aIngress = (RotL64(aWindLaneD[((aIndex + 7676U)) & S_BLOCK1], 52U) ^ RotL64(aWindLaneB[((aIndex + 4548U)) & S_BLOCK1], 13U));
            aIngress ^= (RotL64(aKeyRowReadB[((aIndex + 2125U)) & W_KEY1], 3U) ^ RotL64(aShadowLaneB[((aIndex + 6318U)) & S_BLOCK1], 23U));
            aIngress = TwistMix64::DiffuseC((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneC[((S_BLOCK1 - aIndex + 4632U)) & S_BLOCK1], 12U) ^ RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 4739U)) & S_BLOCK1], 21U));
            aCross ^= (RotL64(aCrystalLaneB[((S_BLOCK1 - aIndex + 5739U)) & S_BLOCK1], 53U) ^ RotL64(aShadowLaneC[((S_BLOCK1 - aIndex + 3784U)) & S_BLOCK1], 41U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 23U) + RotL64(aCross, 5U)) ^ (RotL64(aIngress, 57U) + RotL64(aCarry, 36U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterG = (aWandererE + RotL64(aPrevious, 19U)) + 0x38E4C078511E1B3BULL;
            aOrbiterC = ((aWandererJ + RotL64(aScatter, 53U)) + RotL64(aCarry, 27U)) + 0xC499F6654EE366CAULL;
            aOrbiterF = ((aWandererD + RotL64(aIngress, 11U)) + RotL64(aCarry, 43U)) + 0x79B072F10C4F40B8ULL;
            aOrbiterD = ((aWandererI + RotL64(aCross, 47U)) + 0x8C9533E15698A0D2ULL) + aOASaltE[(((511U - aIndex) + 371U)) & S_SALT1];
            aOrbiterI = ((aWandererH + RotL64(aIngress, 4U)) + 0x4BCD04B010F0BFAAULL) + aOASaltA[(((511U - aIndex) + 469U)) & S_SALT1];
            aOrbiterA = (((aWandererK + RotL64(aCross, 39U)) + RotL64(aCarry, 13U)) + 0x43D563A892249486ULL) + aOASaltC[(((511U - aIndex) + 501U)) & S_SALT1];
            aOrbiterE = (aWandererG + RotL64(aPrevious, 29U)) + 0x7261B4794734FB3DULL;
            //
            aOrbiterG = ((aOrbiterG + aOrbiterC) + 0x66FAC91489332297ULL) + aOUSaltG[((aIndex + 414U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0x61C1189195CC7A8CULL;
            aOrbiterF = RotL64((aOrbiterF * 0xE59D2341DB882FD7ULL), 47U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterI) + 0xC5E0DC1A934C104DULL) + aOUSaltH[((aIndex + 156U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterD) ^ 0xFE4799705F3B8FE2ULL) ^ aOUSaltD[((aIndex + 456U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x79D56A3780EC747BULL), 37U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterA) + 0xE22D3442C933F81EULL) + aOUSaltA[((aIndex + 187U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterC) ^ 0x2B926509212A14B5ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xA92172DB232F3263ULL), 29U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0x1D3A5EC2B6DF484DULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0x4894EDBCB9D34976ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xE36332460F78D085ULL), 13U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0x8B1AE31C407C9EB0ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0x8CF711898AFB4B81ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x9368367DEB3026B7ULL), 57U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterF) + 0x79E7712AFEF126C4ULL) + aOUSaltB[((aIndex + 75U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterI) ^ 0xB0A6B7106A53D9AFULL) ^ aOUSaltC[(((511U - aIndex) + 466U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xCBCBBE63B86C86D9ULL), 23U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0xD25CAA9B853DD42BULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterE) ^ 0xBCD851502EE54B5AULL;
            aOrbiterI = RotL64((aOrbiterI * 0xFB95236BD4C5AB6BULL), 3U);
            //
            aIngress = aOrbiterD ^ RotL64(aOrbiterI, 47U);
            aIngress = aIngress + (RotL64(aOrbiterF, 13U) ^ aOrbiterG);
            aIngress = aIngress + (aOrbiterC ^ RotL64(aOrbiterE, 56U));
            aIngress = aIngress + RotL64(aOrbiterA, 37U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererD = aWandererD ^ ((RotL64(aIngress, 11U) + RotL64(aOrbiterI, 21U)) + aOrbiterE);
            aWandererH = aWandererH + (((RotL64(aCross, 37U) + aOrbiterA) + RotL64(aOrbiterD, 5U)) + RotL64(aCarry, 43U));
            aWandererE = aWandererE ^ (((RotL64(aPrevious, 19U) + aOrbiterG) + RotL64(aOrbiterE, 12U)) + aWUSaltG[((aIndex + 168U)) & S_SALT1]);
            aWandererI = aWandererI + (((RotL64(aScatter, 27U) + RotL64(aOrbiterF, 29U)) + aOrbiterG) + RotL64(aCarry, 19U));
            aWandererJ = aWandererJ ^ (((RotL64(aPrevious, 3U) + RotL64(aOrbiterC, 47U)) + aOrbiterE) + aWUSaltE[((aIndex + 57U)) & S_SALT1]);
            aWandererG = aWandererG + (((RotL64(aIngress, 46U) + RotL64(aOrbiterF, 41U)) + aOrbiterD) + aWUSaltC[(((511U - aIndex) + 183U)) & S_SALT1]);
            aWandererK = aWandererK ^ (((RotL64(aCross, 53U) + RotL64(aOrbiterC, 57U)) + aOrbiterA) + aWUSaltD[(((511U - aIndex) + 351U)) & S_SALT1]);
