            aCross = (RotL64(aCrystalLaneC[((S_BLOCK1 - aIndex + 6458U)) & S_BLOCK1], 52U) ^ RotL64(aCrystalLaneA[((S_BLOCK1 - aIndex + 6041U)) & S_BLOCK1], 29U));
