            aScatter = (RotL64(aIngress, 51U) + RotL64(aCarry, 27U)) ^ (RotL64(aPrevious, 6U) + RotL64(aCross, 39U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterK = ((aWandererJ + RotL64(aScatter, 29U)) + RotL64(aCarry, 13U)) + 0xEB3CFD1348E1594EULL;
            aOrbiterI = ((aWandererA + RotL64(aCross, 47U)) + RotL64(aCarry, 57U)) + 0xD05D332EF9106BEBULL;
