            aWandererC = aWandererC + ((((RotL64(aScatter, 5U) + RotL64(aOrbiterA, 48U)) + aOrbiterK) + RotL64(aCarry, 37U)) + aWUSaltB[(((511U - aIndex) + 283U)) & S_SALT1]);
