            aWandererJ = aWandererJ + ((RotL64(aCross, 39U) + RotL64(aOrbiterH, 19U)) + aOrbiterE);
            aWandererA = aWandererA ^ (((RotL64(aScatter, 19U) + aOrbiterD) + RotL64(aOrbiterJ, 24U)) + aWUSaltH[((aIndex + 294U)) & S_SALT1]);
            //
